# -*- coding: utf-8 -*-
import pathlib
p = pathlib.Path('website/js/store.js')
t = p.read_text(encoding='utf-8')

# ---------- 1. checkout(): promo code ----------
old_checkout = """function checkout(id){if(!user){location.href='login.html';return;}const p=catalog.find(x=>x.id===id);const dialog=document.createElement('dialog');dialog.setAttribute('aria-labelledby','checkout-title');dialog.innerHTML=`<div class="dialog-head"><h2 id="checkout-title">Ваш заказ</h2><button id="close" aria-label="Закрыть">×</button></div><p>${escape(p.name)} · аккаунт ${escape(user.username)}</p><div class="total"><span>Итого</span><strong>${p.price} ₽</strong></div><div class="notice">Деньги не списываются. Заказ сохранится в профиле со статусом «Ожидает подтверждения». Подписка пока не активируется.</div><form id="checkout"><p id="checkout-error" class="error" role="alert"></p><button class="primary">Создать заказ</button></form>`;document.body.append(dialog);dialog.querySelector('#close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();bindForm('#checkout',async()=>{await api('orders',{productId:id});location.href='profile.html?ordered=1';},'#checkout-error');}"""
assert old_checkout in t
new_checkout = """function checkout(id){if(!user){location.href='login.html';return;}const p=catalog.find(x=>x.id===id);const dialog=document.createElement('dialog');dialog.setAttribute('aria-labelledby','checkout-title');dialog.innerHTML=`<div class="dialog-head"><h2 id="checkout-title">Ваш заказ</h2><button id="close" aria-label="Закрыть">×</button></div><p>${escape(p.name)} · аккаунт ${escape(user.username)}</p><div class="promo-row"><input id="promo-code" placeholder="Промокод на скидку (необязательно)" maxlength="24" autocomplete="off"><button type="button" id="promo-apply">Применить</button></div><p id="promo-msg" class="hint" role="status"></p><div class="total"><span>Итого</span><strong id="total-amount">${p.price} ₽</strong></div><div class="notice">Деньги не списываются. Заказ сохранится в профиле со статусом «Ожидает подтверждения». Подписка пока не активируется.</div><form id="checkout"><p id="checkout-error" class="error" role="alert"></p><button class="primary">Создать заказ</button></form>`;document.body.append(dialog);let discount=0;const promoMsg=dialog.querySelector('#promo-msg');const promoInput=dialog.querySelector('#promo-code');const totalEl=dialog.querySelector('#total-amount');const applyPromo=async()=>{const code=promoInput.value.trim().toUpperCase();if(!code){discount=0;promoMsg.textContent='';totalEl.textContent=p.price+' ₽';return;}promoMsg.textContent='Проверяем…';try{const r=await api('promo/validate',{code});discount=r.discount_percent;promoMsg.textContent='Промокод применён: −'+discount+'%';totalEl.textContent=(p.price-Math.round(p.price*discount/100))+' ₽';}catch(e){discount=0;promoMsg.textContent=e.message;totalEl.textContent=p.price+' ₽';}};dialog.querySelector('#promo-apply').onclick=applyPromo;promoInput.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();applyPromo();}};dialog.querySelector('#close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();bindForm('#checkout',async()=>{await api('orders',{productId:id,promo:promoInput.value.trim()||undefined});location.href='profile.html?ordered=1';},'#checkout-error');}"""
t = t.replace(old_checkout, new_checkout, 1)

# ---------- 2. orderList(): show promo discount ----------
old_order = """<small>${date(o.created_at)} · № ${escape(o.id.slice(0,8))}${admin?' · '+escape(o.username):''}</small></div><strong>${o.amount} ₽</strong>"""
assert old_order in t
new_order = """<small>${date(o.created_at)} · № ${escape(o.id.slice(0,8))}${admin?' · '+escape(o.username):''}${o.discount?` · промокод ${escape(o.promo_code)} −${o.discount}%`:''}</small></div><strong>${o.amount} ₽</strong>"""
t = t.replace(old_order, new_order, 1)

# ---------- 3. profile(): cover + sidebar + admin tab ----------
a = t.find('let profileTab=null,profileOrders=null;')
b = t.find('async function admin(){')
assert 0 < a < b
new_profile = r'''let profileTab=null,profileOrders=null;
function downscaleImage(file,w,h,q){return new Promise((res,rej)=>{const img=new Image();const url=URL.createObjectURL(file);img.onload=()=>{try{const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');const scale=Math.max(w/img.width,h/img.height);ctx.drawImage(img,(w-img.width*scale)/2,(h-img.height*scale)/2,img.width*scale,img.height*scale);URL.revokeObjectURL(url);res(canvas.toDataURL('image/jpeg',q));}catch(e){rej(e);}};img.onerror=()=>{URL.revokeObjectURL(url);rej(Error('Не удалось прочитать файл.'));};img.src=url;});}
async function uploadProfileImage(kind,file,statusEl){statusEl.textContent='Загружаем…';try{const dataUrl=await downscaleImage(file,kind==='avatar'?256:1280,kind==='avatar'?256:400,0.85);await api('profile/'+kind,{image:dataUrl});user[kind==='avatar'?'avatar_url':'banner_url']=dataUrl;profileOrders=null;await profile();}catch(e){statusEl.textContent='';const box=document.querySelector('#cover-error');if(box)box.innerHTML=errorBox(e.message);}}
const TAB_NAMES={home:'Главная',security:'Безопасность',admin:'Администрация'};
async function profile(tab){if(!user){auth(false);return;}
if(tab)profileTab=tab;
const available=['home','security'].concat(user.admin?['admin']:[]);
if(profileTab==null||!available.includes(profileTab)){profileTab=new URLSearchParams(location.search).get('tab')||'home';if(!available.includes(profileTab))profileTab='home';}
if(!profileOrders)profileOrders=(await api('orders')).orders;
const orders=profileOrders;
const active=user.lifetime||(user.expires_at&&Date.parse(user.expires_at)>Date.now());
const roleText=user.admin?'Admin':user.beta?'Beta':'Render';
const cover=`<section class="cover"><div class="cover-banner${user.banner_url?' has':''}" id="banner-click" title="Нажмите, чтобы ${user.banner_url?'сменить':'установить'} баннер">${user.banner_url?`<img src="${user.banner_url}" alt="Баннер">`:'<span class="cover-hint">Нажмите, чтобы установить баннер</span>'}<input type="file" id="banner-input" accept="image/png,image/jpeg,image/webp" hidden></div><div class="cover-bar"><div class="cover-avatar" id="avatar-click" title="Нажмите, чтобы ${user.avatar_url?'сменить':'установить'} аватар">${user.avatar_url?`<img src="${user.avatar_url}" alt="Аватар">`:`<span>${escape(user.username[0].toUpperCase())}</span>`}<input type="file" id="avatar-input" accept="image/png,image/jpeg,image/webp" hidden></div><div class="cover-id"><strong>${escape(user.username)}</strong><small>${roleText}${user.frozen?' · Заморожен':''}</small></div>${user.admin?'<span class="cover-badge">Администрация</span>':''}<button type="button" class="cover-mini" id="clear-images">Убрать фото</button></div><p id="cover-error" class="error" role="alert"></p></section>`;
const nav=`<div class="profile-layout"><aside class="pnav"><span class="pnav-title">Разделы</span>${available.map(x=>`<button class="pnav-item${profileTab===x?' active':''}" data-tab="${x}">${TAB_NAMES[x]}</button>`).join('')}</aside><div class="pcontent">`;
const closeNav='</div></div>';
const home=`${new URLSearchParams(location.search).has('ordered')?'<p class="notice" role="status">Заказ создан. Оплата не списана. Ожидайте подтверждения владельцем магазина.</p>':''}<div class="dashboard"><section class="panel"><h2>Личная информация</h2><dl class="data-grid"><div><dt>Логин</dt><dd>${escape(user.username)}</dd></div><div><dt>Почта</dt><dd>${escape(user.email)}</dd></div><div class="wide"><dt>UID</dt><dd>${escape(user.id)}</dd></div><div><dt>Дата регистрации</dt><dd>${date(user.created_at)}</dd></div><div><dt>HWID</dt><dd>${escape(user.hwid||'Не привязан')}</dd></div></dl><p class="hint">Привязка HWID появится после подключения лаунчера. Браузер не определяет идентификатор оборудования.</p><div class="row"><button id="logout">Выйти из аккаунта</button>${user.admin?'<a class="button" href="admin.html">Управление заказами</a>':''}</div></section><section class="panel"><h2>Твоя подписка</h2><div class="subscription">${user.lifetime?'Lifetime':active?'Активна':'Нет активной подписки'}</div><p>${user.frozen?'<strong>Аккаунт заморожен администрацией.</strong>':user.lifetime?'Бессрочный доступ':active?'До '+date(user.expires_at):user.expires_at?'Истекла '+date(user.expires_at):'Выбери подходящий срок в магазине.'}</p><p>Beta: ${user.beta?'активна':'не подключена'}</p><a class="button primary" href="shop.html">${user.lifetime?'Дополнение Beta':'Выбрать подписку'}</a></section></div><section class="orders"><h2>История заказов</h2><p>Здесь появляются заказы и их текущий статус.</p><div id="message" role="alert"></div>${orderList(orders)}</section>`;
const sec=`<section class="panel profile-pass"><h2>Безопасность</h2><p>Для смены пароля потребуется текущий. После смены пароля все другие сессии автоматически выйдут из аккаунта.</p><form id="password">${field('Текущий пароль','currentPassword','password','autocomplete="current-password" maxlength="128"')}${field('Новый пароль','newPassword','password','autocomplete="new-password" minlength="10" maxlength="128" placeholder="Не менее 10 символов"')}<p id="form-error" class="error" role="alert"></p><button>Сменить пароль</button></form><p class="hint">Используй уникальный пароль, который не применяешь больше нигде. Сессия хранится 7 дней.</p></section>`;
const adminView=`<div id="message" role="alert"></div><section class="panel"><h2>Промокоды на скидку</h2><p>Скидка применяется к цене тарифа при создании заказа. Бессрочный промокод действует, пока не кончатся использования.</p><form id="promo-create"><div class="form-grid">${field('Код','code','text','autocomplete="off" pattern="[A-Za-z0-9_-]{3,24}" maxlength="24" placeholder="HORUS10"')}${field('Скидка, %','discount','number','min="1" max="90" value="10"')}${field('Использований','uses','number','min="1" max="9999" value="10"')}${field('Срок, дней (0 — бессрочно)','days','number','min="0" max="365" value="0"')}</div><p id="promo-error" class="error" role="alert"></p><button class="primary">Создать промокод</button></form><div id="promo-list" class="promo-list"><small>Загрузка…</small></div></section><section class="panel"><h2>Выдача подписки</h2><p>Начислит выбранный тариф на аккаунт сразу, без заказа и оплаты.</p><form id="grant-form"><div class="form-grid">${field('Логин','username','text','pattern="[a-zA-Z0-9_]{3,24}" maxlength="24" placeholder="Логин игрока")}<label>Тариф<select name="product"><option value="30d">30 дней</option><option value="90d">90 дней</option><option value="lifetime">Lifetime</option><option value="beta">Beta</option></select></label></div><p id="grant-error" class="error" role="alert"></p><button class="primary">Выдать</button></form></section><section class="panel"><h2>Заморозка подписки</h2><p>Замороженный аккаунт не может создавать заказы, пока его не разморозят.</p><form id="freeze-form"><div class="form-grid">${field('Логин','username','text','pattern="[a-zA-Z0-9_]{3,24}" maxlength="24" placeholder="Логин игрока")}<label>Действие<select name="mode"><option value="freeze">Заморозить</option><option value="unfreeze">Разморозить</option></select></label></div><p id="freeze-error" class="error" role="alert"></p><button>Применить</button></form></section>`;
shell(cover+nav+(profileTab==='home'?home:profileTab==='security'?sec:adminView)+closeNav);
document.querySelectorAll('.pnav-item').forEach(btn=>btn.onclick=()=>{profileTab=btn.dataset.tab;history.replaceState(null,'',profileTab==='home'?'profile.html':'profile.html?tab='+profileTab);profile();});
document.querySelector('#avatar-click').onclick=()=>document.querySelector('#avatar-input').click();
document.querySelector('#banner-click').onclick=()=>document.querySelector('#banner-input').click();
document.querySelector('#avatar-input').onchange=e=>{const f=e.target.files[0];if(f)uploadProfileImage('avatar',f,document.querySelector('.cover-avatar'));e.target.value='';};
document.querySelector('#banner-input').onchange=e=>{const f=e.target.files[0];if(f)uploadProfileImage('banner',f,document.querySelector('.cover-banner'));e.target.value='';};
document.querySelector('#clear-images').onclick=async e=>{await action(e.currentTarget,async()=>{await api('profile/clear-image',{field:'avatar'});await api('profile/clear-image',{field:'banner'});user.avatar_url=null;user.banner_url=null;profileOrders=null;await profile();});};
if(profileTab==='home'){
document.querySelector('#logout').onclick=async e=>{await action(e.currentTarget,async()=>{await api('logout',{});profileOrders=null;location.href='index.html';});};
document.querySelectorAll('[data-cancel]').forEach(btn=>btn.onclick=()=>action(btn,async()=>{await api('orders/'+btn.dataset.cancel+'/cancel',{});profileOrders=null;await profile('home');}));
}
if(profileTab==='admin'){
bindForm('#promo-create',async form=>{const data=Object.fromEntries(new FormData(form));await api('admin/promos',{code:data.code,discount:data.discount,uses:data.uses,days:data.days});form.reset();document.querySelector('#promo-error').textContent='Промокод создан.';loadPromoList();},'#promo-error');
bindForm('#grant-form',async form=>{const data=Object.fromEntries(new FormData(form));const r=await api('admin/grant',{username:data.username,product:data.product});document.querySelector('#grant-error').textContent='Готово: '+r.username+' получил тариф.';form.reset();},'#grant-error');
bindForm('#freeze-form',async form=>{const data=Object.fromEntries(new FormData(form));const r=await api('admin/freeze',{username:data.username,frozen:data.mode==='freeze'});document.querySelector('#freeze-error').textContent=r.username+(r.frozen?' заморожен.':' разморожен.');form.reset();},'#freeze-error');
loadPromoList();
}
if(document.querySelector('#password'))bindForm('#password',async form=>{await api('password',Object.fromEntries(new FormData(form)));form.reset();document.querySelector('#form-error').textContent='Пароль изменён.';});}
async function loadPromoList(){const el=document.querySelector('#promo-list');if(!el)return;try{const {promos}=await api('admin/promos');el.innerHTML=promos.length?promos.map(x=>`<div class="promo-item"><code>${escape(x.code)}</code><span>−${x.discount_percent}%</span><small>${x.uses_left} исп.${x.expires_at?' · до '+date(x.expires_at):' · бессрочно'}</small><button data-del-promo="${escape(x.code)}">Удалить</button></div>`).join(''):'<small>Промокодов пока нет.</small>';el.querySelectorAll('[data-del-promo]').forEach(btn=>btn.onclick=()=>action(btn,async()=>{await api('admin/promos/delete',{code:btn.dataset.delPromo});await loadPromoList();}));}catch(e){el.innerHTML=errorBox(e.message);}}
'''
t = t[:a] + new_profile + t[b:]
p.write_text(t, encoding='utf-8')
print('store.js profile rewritten')
